    "faq.q1": {
      "group": "Frequently asked",
      "where": [
        "index.html",
        "our-services.html",
        "get-in-touch.html"
      ],
      "label": "Question",
      "en": "What services does ING provide?",
      "ar": "ما الخدمات التي تقدمها ING؟",
      "href": "",
      "langs": [
        "en",
        "ar"
      ],
      "labelAr": "سؤال"
    },
    "faq.a1": {
      "group": "Frequently asked",
      "where": [
        "index.html",
        "our-services.html",
        "get-in-touch.html"
      ],
      "label": "Answer",
      "en": "ING provides warehouse services management — receiving and dispatch, unloading, storage and put-away, inventory control and quality control — plus value-added operations such as order picking, packing, labeling and palletizing, track and trace, and various offices for work.",
      "ar": "تقدم ING اداره الخدمات المستودعيه — الاستلام والارسال والتنزيل والتخزين والترتيب وضبط المخزون وضبط الجوده — اضافة الى العمليات ذات القيمه المضافه كالتقاط الطلبات والتعبئه ووضع الملصقات والتشكيل على المنصات، والتتبع والتعقب، ومكاتب متنوعه للعمل.",
      "href": "",
      "langs": [
        "en",
        "ar"
      ],
      "labelAr": "جواب"
    },
    "faq.q2": {
      "group": "Frequently asked",
      "where": [
        "index.html",
        "our-services.html",
        "get-in-touch.html"
      ],
      "label": "Question",
      "en": "Can I track my shipment?",
      "ar": "هل يمكنني تتبع شحنتي؟",
      "href": "",
      "langs": [
        "en",
        "ar"
      ],
      "labelAr": "سؤال"
    },
    "faq.a2": {
      "group": "Frequently asked",
      "where": [
        "index.html",
        "our-services.html",
        "get-in-touch.html"
      ],
      "label": "Answer",
      "en": "Yes. ING provides a track and trace service that lets customers follow the status of their order from receipt through to delivery.",
      "ar": "نعم، توفر ING خدمه التتبع والتعقب التي تمكن العملاء من متابعه حاله الطلب بدءا من استلامه وانتهاء من تسليمه.",
      "href": "",
      "langs": [
        "en",
        "ar"
      ],
      "labelAr": "جواب"
    },
